const mongoose = require('mongoose');
const cleanJson = require('../utils/cleanJson');

// Flashcard piles for one lecture. Card ids are the "fc_<lineIndex>" ids
// generated by initFlashcards() in frontend/js/app.js.
const flashcardStateSchema = new mongoose.Schema(
  {
    lecture: { type: mongoose.Schema.Types.ObjectId, ref: 'Lecture', required: true },
    known: { type: [String], default: [] },
    studying: { type: [String], default: [] }
  },
  { _id: false }
);

// Exactly one progress document per user (enforced by the unique index),
// replacing the old momento_streak_v1 and momento_fc_states_<id> keys.
const studyProgressSchema = new mongoose.Schema(
  {
    user: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true, unique: true },
    currentStreak: { type: Number, default: 0, min: 0 },
    bestStreak: { type: Number, default: 0, min: 0 },
    lastStudyDate: { type: Date, default: null },
    flashcards: { type: [flashcardStateSchema], default: [] }
  },
  {
    timestamps: true,
    toJSON: { transform: cleanJson }
  }
);

// Returns the user's progress document, creating an empty one the first time.
studyProgressSchema.statics.findOrCreateForUser = async function findOrCreateForUser(userId) {
  return this.findOneAndUpdate(
    { user: userId },
    { $setOnInsert: { user: userId } },
    { upsert: true, returnDocument: 'after', setDefaultsOnInsert: true }
  );
};

module.exports = mongoose.model('StudyProgress', studyProgressSchema);
